package geo
import ("strconv"; "strings")
func ParseGridRef(raw string) (string, int) {
    parts := strings.SplitN(strings.TrimSpace(raw), "-", 2)
    if len(parts) != 2 { return "", 0 }
    row, _ := strconv.Atoi(parts[1])
    return parts[0], row
}
func GridLabel(zone string, row int) string { return zone + "-" + strconv.Itoa(row) }

