package geo
import "testing"
func TestPaddedGrid(t *testing.T) {
    zone, row := ParseGridRef("  B-17  ")
    if zone != "B" || row != 17 { t.Fatal(zone, row) }
}
func TestGridLabel(t *testing.T) {
    if GridLabel("B", 17) != "B-17" { t.Fatal("label") }
}
